export const meta = {
  "slug": "phosphor-bag",
  "family": "phosphor",
  "name": "bag",
  "category": "Commerce",
  "motion": "bounce",
  "component": "createPhosphorBagIcon"
};

export function createPhosphorBagIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
